        /// <summary>
        /// Represents a single dynamic data entry for kernel or core configuration.
        /// </summary>
        [StructLayout(LayoutKind.Sequential, Pack = 1)]
        public struct DynDataEntry
        {
            /// <summary>
            /// The class type.
            /// </summary>
            public UInt16 Class;
            /// <summary>
            /// The machine architecture code.
            /// </summary>
            public UInt16 Machine;
            /// <summary>
            /// The image timestamp.
            /// </summary>
            public UInt32 TimeDateStamp;
            /// <summary>
            /// The image size.
            /// </summary>
            public UInt32 SizeOfImage;
            /// <summary>
            /// The offset to the field data.
            /// </summary>
            public UInt32 Offset;
        }

        /// <summary>
        /// Represents kernel field offsets for dynamic configuration.
        /// </summary>
        [StructLayout(LayoutKind.Sequential, Pack = 1)]
        public struct DynFieldsKernel
        {
            public UInt16 EgeGuid;
            public UInt16 EpObjectTable;
            public UInt16 EreGuidEntry;
            public UInt16 HtHandleContentionEvent;
            public UInt16 OtName;
