        /// <summary>
        /// Generates and writes dynamic configuration files and headers.
        /// </summary>
        /// <param name="OutDir">The output directory for the config file.</param>
        /// <param name="StrictChecks">Whether to enforce strict signature checks.</param>
        /// <returns>True if successful; otherwise, false.</returns>
        public static bool Execute(string OutDir, bool StrictChecks)
        {
            string manifestFile = Path.Join([Build.BuildWorkingFolder, "\\kphlib\\kphdyn.xml"]);
            string hardwareFile = Path.Join([Build.BuildWorkingFolder, "\\kphlib\\kphdynhw.xml"]);
            string headerFile = Path.Join([Build.BuildWorkingFolder, "\\kphlib\\include\\kphdyn.h"]);

            DynDataHw.VerifyLayouts();

            // Check for new or modified content. We don't want to touch the file if it's unnecessary.
            {
                Utils.WriteTextIfChanged(headerFile, GenerateHeader);

                Program.PrintColorMessage($"Dynamic header -> {headerFile}", ConsoleColor.Cyan);
            }

            if (!File.Exists(hardwareFile))
                throw new FileNotFoundException("The hardware allow-list is required to build dynamic data.", hardwareFile);

            byte[] config = GenerateConfig(manifestFile, [hardwareFile]);

            if (string.IsNullOrWhiteSpace(OutDir))
                return true;

            Win32.CreateDirectory(OutDir);

            string configFile = Path.Join([OutDir, "\\ksidyn.bin"]);

            if (File.Exists(configFile))
            {
                var configUpdateBytes = Utils.ReadAllBytes(configFile).AsSpan();
                var configSigFileName = Path.ChangeExtension(configFile, ".sig");

                if (configUpdateBytes.SequenceEqual(config) && BuildVerify.IsValidKphSigFile(configSigFileName))
                {
                    Program.PrintColorMessage($"Dynamic config -> {configFile}", ConsoleColor.Cyan);
                    return true;
                }

                File.Delete(configFile);
                File.Delete(configSigFileName);
                Utils.WriteAllBytes(configFile, config);

                bool configFileSig = BuildVerify.CreateSigFile("kph", configFile, StrictChecks);

                Program.PrintColorMessage($"Dynamic config -> {configFile}", ConsoleColor.Cyan);

                return configFileSig;
            }
            else
            {
                Utils.WriteAllBytes(configFile, config);

                bool configFileSig = BuildVerify.CreateSigFile("kph", configFile, StrictChecks);

                Program.PrintColorMessage($"Dynamic config -> {configFile}", ConsoleColor.Cyan);

                return configFileSig;
            }
        }

        /// <summary>
        /// Generates and writes dynamic configuration files and headers.
        /// </summary>
        /// <returns>True if successful; otherwise, false.</returns>
        private static void GenerateHeader(TextWriter sb)
        {
            sb.WriteLine(FileHeader);
            sb.WriteLine();
            sb.WriteLine("#pragma once");
            sb.WriteLine();
            sb.WriteLine(Includes);
            sb.WriteLine(DynConfigC);
        }

        /// <summary>
        /// Generates the dynamic configuration binary from the manifest XML.
        /// </summary>
        /// <param name="ManifestFile">The manifest XML file path.</param>
        /// <param name="HardwareFiles">The hardware manifest XML file paths; no hardware section when empty.</param>
        /// <returns>The configuration binary as a byte array.</returns>
        private static byte[] GenerateConfig(string ManifestFile, string[] HardwareFiles)
        {
            var xml = new XmlDocument();

            var xmlSettings = new XmlReaderSettings
            {
                DtdProcessing = DtdProcessing.Prohibit,
                IgnoreWhitespace = true
            };
            using (var xmlReader = XmlReader.Create(ManifestFile, xmlSettings))
            {
                xml.Load(xmlReader);
            }

            var dyn = xml.SelectSingleNode("/dyn");
            var dataNodes = dyn?.SelectNodes("data");
            var fieldsNodes = dyn?.SelectNodes("fields");

            if (dataNodes == null)
                return null;
            if (fieldsNodes == null)
                return null;

            var fieldsStream = new ArrayBufferWriter<byte>();
            var fieldsMap = new Dictionary<UInt32, XmlNode>(fieldsNodes.Count);
            var fieldsOffsets = new Dictionary<UInt32, UInt32>(fieldsNodes.Count);
            var entries = new List<DynDataEntry>(dataNodes.Count);

            foreach (XmlNode field in fieldsNodes)
            {
                var name = field.Attributes?.GetNamedItem("id")?.Value;

                if (string.IsNullOrWhiteSpace(name))
                    continue;

                fieldsMap.Add(UInt32.Parse(name.AsSpan()), field);
            }

            foreach (XmlNode data in dataNodes)
            {
                var file = data.Attributes?.GetNamedItem("file")?.Value;
                var arch = data.Attributes?.GetNamedItem("arch")?.Value;
                var timestamp = data.Attributes?.GetNamedItem("timestamp")?.Value;
                var size = data.Attributes?.GetNamedItem("size")?.Value;
                var dynClass = ClassFromString(file);

                if (string.IsNullOrWhiteSpace(timestamp))
                    continue;
                if (string.IsNullOrWhiteSpace(size))
                    continue;

                DynDataEntry entry = new DynDataEntry
                {
                    Class = (UInt16)dynClass,
                    Machine = MachineFromString(arch),
                    TimeDateStamp = UInt32.Parse(timestamp.AsSpan(2), NumberStyles.HexNumber),
                    SizeOfImage = UInt32.Parse(size.AsSpan(2), NumberStyles.HexNumber)
                };

                var fieldId = UInt32.Parse(data.InnerText.AsSpan());

                if (!fieldsOffsets.TryGetValue(fieldId, out UInt32 offset))
                {
                    offset = (UInt32)fieldsStream.WrittenCount;
                    fieldsOffsets.Add(fieldId, offset);

                    switch (dynClass)
                    {
                    case ClassType.Ntoskrnl:
                    case ClassType.Ntkrla57:
                        {
                            var fieldsData = new DynFieldsKernel();
                            var fieldNodes = fieldsMap[fieldId].SelectNodes("field");

                            if (fieldNodes != null)
                            {
                                foreach (XmlNode field in fieldNodes)
                                {
                                    string value = field.Attributes?.GetNamedItem("value")?.Value;
                                    string name = field.Attributes?.GetNamedItem("name")?.Value;

                                    if (string.IsNullOrWhiteSpace(name) || string.IsNullOrWhiteSpace(value))
                                        continue;

                                    if (DynFieldsKernelFieldCache.TryGetValue(name, out var member))
                                    {
                                        member.SetValueDirect(__makeref(fieldsData), UInt16.Parse(value.AsSpan(2), NumberStyles.HexNumber));
                                    }
                                }
                            }

                            fieldsStream.Write(MemoryMarshal.AsBytes(MemoryMarshal.CreateSpan(ref fieldsData, 1)));
                        }
                        break;
                    case ClassType.Lxcore:
                        {
                            var fieldsData = new DynFieldsLxcore();
                            var fieldNodes = fieldsMap[fieldId].SelectNodes("field");

                            if (fieldNodes != null)
                            {
                                foreach (XmlNode field in fieldNodes)
                                {
                                    string value = field.Attributes?.GetNamedItem("value")?.Value;
                                    string name = field.Attributes?.GetNamedItem("name")?.Value;

                                    if (string.IsNullOrWhiteSpace(name) || string.IsNullOrWhiteSpace(value))
                                        continue;

                                    if (DynFieldsLxcoreFieldCache.TryGetValue(name, out var member))
                                    {
                                        member.SetValueDirect(__makeref(fieldsData), UInt16.Parse(value.AsSpan(2), NumberStyles.HexNumber));
                                    }
                                }
                            }

                            fieldsStream.Write(MemoryMarshal.AsBytes(MemoryMarshal.CreateSpan(ref fieldsData, 1)));
                        }
                        break;
                    default:
                        {
                            throw new InvalidOperationException($"invalid class {dynClass}");
                        }
                    }
                }

                entry.Offset = offset;

                entries.Add(entry);
            }

            // Build the hardware section, if there is a hardware manifest.
            byte[] hardware = [];

            if (HardwareFiles.Length != 0)
            {
                var hardwareRows = HwManifest.Load(HardwareFiles);

                hardware = HwSection.Serialize(hardwareRows, out int hardwareTables);

                Program.PrintColorMessage($"Dynamic hardware -> {hardwareRows.Count} rows, {hardwareTables} tables, {hardware.Length} bytes, SHA-256 {Convert.ToHexString(SHA256.HashData(hardware))}", ConsoleColor.Cyan);
            }

            // Allocate a pre-sized buffer for the entire configuration binary.
            // The size is calculated as: Version (4) + Public Key Length + Count (4) + HardwareOffset (4) +
            // HardwareLength (4) + (Entries * EntrySize) + Fields Data Length + Hardware Section Length.
            int hardwareOffset = sizeof(uint) +
                                 SessionTokenPublicKey.Length +
                                 sizeof(uint) +
                                 sizeof(uint) +
                                 sizeof(uint) +
                                 (entries.Count * Unsafe.SizeOf<DynDataEntry>()) +
                                 fieldsStream.WrittenCount;
            byte[] result = new byte[hardwareOffset + hardware.Length];
            // Create a span over the result buffer for efficient writing.
            Span<byte> span = result;

            // Write the configuration version in little-endian format and advance the span.
            BinaryPrimitives.WriteUInt32LittleEndian(span, Version);
            span = span[sizeof(uint)..];

            // Copy the session token public key into the buffer and advance the span.
            SessionTokenPublicKey.CopyTo(span);
            span = span[SessionTokenPublicKey.Length..];

            // Write the count of dynamic data entries and advance the span.
            BinaryPrimitives.WriteUInt32LittleEndian(span, (uint)entries.Count);
            span = span[sizeof(uint)..];

            // Write the hardware section offset (absolute, 0 = absent) and length and advance the span.
            BinaryPrimitives.WriteUInt32LittleEndian(span, hardware.Length != 0 ? (uint)hardwareOffset : 0);
            span = span[sizeof(uint)..];
            BinaryPrimitives.WriteUInt32LittleEndian(span, (uint)hardware.Length);
            span = span[sizeof(uint)..];

            // Convert the entry list to a read-only byte span and copy it to the buffer.
            ReadOnlySpan<byte> entriesSpan = MemoryMarshal.AsBytes(CollectionsMarshal.AsSpan(entries));
            entriesSpan.CopyTo(span);
            span = span[entriesSpan.Length..];

            // Copy the field data from the ArrayBufferWriter and advance the span.
            fieldsStream.WrittenSpan.CopyTo(span);
            span = span[fieldsStream.WrittenCount..];

            // Copy the hardware section to the remaining buffer space.
            hardware.CopyTo(span);

            return result;
        }

        /// <summary>
        /// Validates the session token public key.
        /// </summary>
        /// <returns>True if the key is valid; otherwise, false.</returns>
        public static bool IsValidSessionKey()
        {
            try
            {
                const int RsaLength = 539;
                const int MlDsaLength = 2592;

                if (SessionTokenPublicKey.Length != RsaLength + MlDsaLength)
                {
                    Program.PrintColorMessage(
                        $"Session token public key container is {SessionTokenPublicKey.Length} bytes, expected {RsaLength + MlDsaLength}.",
                        ConsoleColor.Red);
                    return false;
                }

                BuildVerify.PrintCngPublicKeyInfo(SessionTokenPublicKey[..RsaLength], CngKeyBlobFormat.GenericPublicBlob);
                Program.PrintColorMessage($"ML-DSA-87 public key: {MlDsaLength} bytes", ConsoleColor.DarkGray);
            }
            catch (Exception ex)
            {
                Program.PrintErrorMessage(ex);
                return false;
            }

            return true;
        }
    }
}
